              "pinyin": "Dànshì xiànzài, yīnwèi yǒu le gèngduō de lìliàng hé shēngliàng, wǒmen kěyǐ yǒu gèngduō de jīhuì, lìyòng zìshēn de yǐngxiǎnglì hé shèqū de xíngdònglì, qù guānzhù hé jièrù dào guónèi wèntí shàng.”",
