              "cn": "山东的一位网友说：“学校有很多老师在课外开展补习班，自己从中谋利，并且有很多腐败，在国际级别考试透露题型。”",
              "pinyin": "Shāndōng de yíwèi wǎngyǒu shuō: “xuéxiào yǒu hěnduō lǎoshī zài kèwài kāizhǎn bǔxíbān, zìjǐ cóngzhōng móulì, bìngqiě yǒu hěnduō fǔbài, zài guójì jíbié kǎoshì tòulù tíxíng.”",
              "en": "A user from Shandong said: \"Many teachers at the school run tutoring classes outside lessons to make money for themselves, and there's a lot of corruption, like leaking the question types for international-level exams.\"",
