              "id": "s6_8_9",
              "cn": "在这之前，初一开始就要每天上晚自习，初三更是每天要学很久很久。",
              "pinyin": "Zài zhè zhīqián, chūyì kāishǐ jiù yào měitiān shàng wǎnzìxí, chūsān gèngshì měitiān yào xué hěnjiǔ hěnjiǔ.",
