              "cn": "纽约大学斯坦哈特文化教育和人类发展学院研究和公平副院长程华宇说，“我认为职业教育是一个很好的可行选择。",
              "pinyin": "Niǔyuē dàxué Sītǎnhātè wénhuà jiàoyù hé rénlèi fāzhǎn xuéyuàn yánjiū hé gōngpíng fù yuànzhǎng Chénghuáyǔ shuō, “wǒ rènwéi zhíyèjiàoyù shì yígè hěn hǎo de kěxíng xuǎnzé.",
              "en": "Cherng, the NYU Steinhardt vice dean, said: \"I think vocational education is a good, workable option.",
